    39|  try {
    40|    const res = await fetch(`${API_BASE}${path}`, {
    41|      method: 'POST',
    42|      headers: { 'Content-Type': 'application/json' },
    43|      body: JSON.stringify(body),
    44|    });
    45|    if (!res.ok) {
    46|      return { ok: false, error: `Request failed (${res.status})` };
    47|    }
