   125|async function apiFetch<T>(path: string, options: RequestInit = {}): Promise<T> {
   126|  const url = `${API_BASE}${path}`;
   127|  const res = await fetch(url, {
   128|    ...options,
   129|    headers: { ...getAuthHeaders(), ...(options.headers as Record<string, string> || {}) },
   130|  });
   131|  if (!res.ok) {
   132|    const body = await res.text();
   133|    throw new Error(`API ${res.status}: ${body.slice(0, 200)}`);
