   140|export async function fetchProjectMedia(projectId: string): Promise<{ images: ProjectMedia[]; videos: ProjectVideo[] }> {
   141|  const { data: media } = await supabase
   142|    .from('project_media')
   143|    .select('*')
   144|    .eq('project_id', projectId)
   145|    .eq('is_approved', true)
   146|    .order('position', { ascending: true });
   147|
   148|  const { data: videos } = await supabase
   149|    .from('project_videos')
   150|    .select('*')
   151|    .eq('project_id', projectId)
   152|    .eq('is_approved', true)
   153|    .order('is_pinned', { ascending: false });
   154|
   155|  const images = (media || []).filter((m: ProjectMedia) => m.media_type === 'image');
   156|  const allVideos = (videos || []) as ProjectVideo[];
   157|
   158|  return { images, videos: allVideos };
