   281|// ── Comments ───────────────────────────────────────────────────────────────
   282|
   283|export async function fetchProjectComments(
   284|  projectId: string,
   285|  limit = 20,
   286|  offset = 0,
   287|): Promise<{ comments: ProjectComment[]; total: number }> {
   288|  const { data, count } = await supabase
   289|    .from('project_comments')
   290|    .select('*', { count: 'exact' })
   291|    .eq('project_id', projectId)
   292|    .eq('is_approved', true)
   293|    .is('deleted_at', null)
   294|    .is('parent_id', null)
   295|    .order('created_at', { ascending: false })
   296|    .range(offset, offset + limit - 1);
   297|
   298|  // Fetch replies for each comment
   299|  const comments = await Promise.all(
   300|    (data || []).map(async (comment: ProjectComment) => {
   301|      const { data: replies } = await supabase
   302|        .from('project_comments')
   303|        .select('*')
   304|        .eq('parent_id', comment.id)
   305|        .eq('is_approved', true)
   306|        .is('deleted_at', null)
   307|        .order('created_at', { ascending: true });
   308|
   309|      // Get user name if available
   310|      let userName = comment.guest_name || 'Investor';
   311|      if (comment.user_id) {
   312|        const { data: profile } = await supabase
   313|          .from('profiles')
   314|          .select('first_name, last_name')
   315|          .eq('id', comment.user_id)
   316|          .maybeSingle();
   317|        if (profile) {
   318|          userName = `${(profile as any).first_name || ''} ${(profile as any).last_name || ''}`.trim() || 'Investor';
   319|        }
   320|      }
   321|
   322|      return {
   323|        ...comment,
   324|        user_name: comment.is_owner_reply ? 'IVX Team' : userName,
   325|        replies: (replies || []).map((r: ProjectComment) => ({
   326|          ...r,
   327|          user_name: r.is_owner_reply ? 'IVX Team' : (r.guest_name || 'Investor'),
   328|        })),
   329|      };
   330|    }),
   331|  );
   332|
   333|  return { comments, total: count ?? 0 };
