async function writeDoc<T>(name: string, value: T): Promise<void> {
  const { PutObjectCommand } = await import('@aws-sdk/client-s3');
  const s3 = await getS3();
  await s3.send(new PutObjectCommand({
    Bucket: bucket(),
    Key: `${PLATFORM_PREFIX}/${name}`,
