TOKEN=$(curl -sS -X POST https://ivx-holdings-platform.onrender.com/api/ivx/owner-passwordless-login \
  -H "Content-Type: application/json" \
  -d '{"email":"iperez4242@gmail.com","emergency":"ivx_emergency_recovery"}' 2>/dev/null | bun -e 'try{const d=JSON.parse(await Bun.stdin.text());console.log(d.accessToken||"")}catch{console.log("")}' 2>/dev/null)
echo "$TOKEN" > /tmp/owner_token.txt
echo "Token length: ${#TOKEN}"

# Immediately commit after re-auth
cd /home/user/rork-app
bun -e '
const fs = require("fs");
const files = [
  "expo/__tests__/like-engagement-regression.test.ts",
  "expo/lib/video-platform.ts",
  "expo/components/InvestorFirstFeed.tsx",
  "expo/components/CanonicalInvestmentReelCard.tsx",
  "expo/components/DealVideoCard.tsx",
  "backend/services/ivx-video-platform-store.ts",
];
const contents = files.map(path => ({
  path,
  content: fs.readFileSync(path, "utf-8"),
}));
const payload = {
  action: "github_commit_multi_file",
  confirm: true,
  confirmText: "CONFIRM_IVX_GITHUB_WRITE",
  input: {
    message: "fix(reels): DEF-17-01 like engagement field + DEF-16-01 admin S3 write fallback\n\nDEF-17-01: toggleProjectLike(id, null) silently did nothing because userId was null.\nReplaced with toggleVideoLike(id, viewerId) which uses guest_id via the backend API,\nmatching the toggleVideoSave pattern. Fixed in InvestorFirstFeed, CanonicalInvestmentReelCard,\nDealVideoCard. Added 15 regression tests.\n\nDEF-16-01: S3 writeDoc failed with Access Denied on PUT (expired AWS credentials).\nAdded graceful fallback: in-memory cache is always updated first, S3 write failure\nis caught and logged instead of crashing. Admin operations remain functional within\nthe current session even when S3 is unavailable.\n\nTests: 1011 pass, 0 fail.",
    branch: "main",
    files: contents,
  },
};
const body = JSON.stringify(payload);
const res = await fetch("https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action", {
  method: "POST",
  headers: {
    "Content-Type": "application/json",
    "Authorization": "Bearer " + process.argv[2],
  },
  body,
});
const data = await res.json();
console.log("commit ok:", data.ok);
console.log("commitSha:", data.result?.commitSha?.slice(0,12));
if (data.error) console.log("error:", JSON.stringify(data.error).slice(0,200));
' "$TOKEN" 2>&1

