sha256sum "$APK_PATH"
echo ""
echo "--- APK version info ---"
cd /home/user/rork-app/expo/android
bun -e '
const fs = require("fs");
const path = require("path");
// Read build.gradle for version info
const gradle = fs.readFileSync("app/build.gradle", "utf-8");
const versionNameMatch = gradle.match(/versionName\s+"([^"]+)"/);
const versionCodeMatch = gradle.match(/versionCode\s+(\d+)/);
